/*
Live GLSL fragment shader demonstrating the different improvements with our method.
Explained in paper "Fast sphere tracing of procedural volumetric noise for very large and detailed scenes" (https://onlinelibrary.wiley.com/share/author/CCXF88UYBB2GJEYQRZXU?target=10.1111/cgf.70072)
(To be) presented at Eurographics 2025.

Keyboard controls:

    Step size computation options :
        default: ours
        n: naive
        c: custom (overwrites with below)
            a: Adaptive lip const, s: Substeps, e: Earlystop+1, q: Quadratic inclusion function (+ i: Improved quad.)
    h: Octave heatmap visu (proportional to perf)
    1: plain field of Perlin FBM
    2: Hypertextured Sphere
    3: Hypertextured Arlo (Courtsey of Inigo Quilez, https://www.shadertoy.com/view/4dtGWM)


Copyright: Anyone is free to use this code. (Linking to either this shadertoy or the original paper is encouraged but not mandatory.)
*/




// ========== PARAMETERS ==========
//    === CAMERA RELATED ===
float scale = 0.4; // Camera scale
//float scale = 0.6; // Camera scale
//#define iMOUSE_OVERWRITE vec2(1802.6,345.5)
//#define SCALE_OVERWRITE 0.1949

//    === VISU MODES ===
#define DO_DISTANCE_VISU 1
#define DO_STEP_VISU 1
#define DO_TOTAL_OCT_VISU 0
#define DO_OCT_PER_STEP_VISU 0
#define DO_TOTAL_OCT_HEATMAP_VISU 2  // 1: whole screen, 2: half screen
    #define TOTAL_OCT_SHADING_LOW_TRESH 0 
    #define TOTAL_OCT_SHADING_HIGH_TRESH 2500 // Used to adapt colors of the heatmap

//    === SCENE BBOX ===
#define ENABLE_BBOX 1
#define BBOX_SCALE 2.

//    === FBM SPHERE TRACING OPTIONS ===
#define KEYBOARD_CONTROLED_OPTIONS true // If true, overwrites the following with keyboard controls
    #define DO_RAY_MARCHING false
    #define DO_USE_GLOBAL_LIP false            // Classical Sphere Tracing

    #define DO_SUBSTEPPING true                // Sub-Stepping
    #define DO_EARLY_STOP true
    #define EARLY_STOP_PLUS_K 1
    #define DO_QUAD_SKIP true                  // Use quadratic Taylor inclusion function
    #define USE_IMPROVED_QUAD true
    #define DO_FULL_COMP_FOR_SIGN 0.           // Usefull for volumetric rendering (not in this shader)


//    === FBM GLOBAL PARAMS ===
int FBM_OCTAVE = 16;        // Number of octaves used for FBM
float FBM_BASE_SCALE = 1.0; // Scaling of the first base octave
float FBM_TRESH = 0.15;     // Global constant threshold (if not using USE_AFFINE_THRESHOLD below)
float BETA = 1.0;           // Lacunarity-related parameter. Range: ]0:2]

//    === FBM noise function def ===
#define OVERWIRTE_FBM_BASE_NOISE_FUNCTIONS
#ifdef OVERWIRTE_FBM_BASE_NOISE_FUNCTIONS
vec2 FBM_base_noise_OVERWRITE(vec3 p, vec3 rd, bool should_comp_grad){
    vec2 noise = perlin3D_with_der(p, rd, true);
    // noise = abs(noise); // not compatible with quadratic incl. function.
    return noise;
}
vec4 FBM_base_noise_lip_consts_OVERWRITE(){
    vec4 lip_consts = vec4(0.);
    lip_consts.x = max_base_perlin_derivative;
    lip_consts.y = max_base_perlin_scd_derivative;
    return lip_consts;
}
#endif

// ========== AFFINE THRESHOLD DEF ==========
#define USE_AFFINE_THRESHOLD
#ifndef OVERWRITE_AFFINE_THRESHOLD_DEF
#define OVERWRITE_AFFINE_THRESHOLD_DEF
float SDF_to_hypertexture(vec3 p){
    return length(p)-0.7;
}


void get_noise_params(inout vec3 p, vec3 rd, int octave, in float noise_threshold, out vec2 noise_varying_threshold){
    noise_varying_threshold = vec2(0.);
    float noise_threshold_a=0., noise_threshold_b=FBM_TRESH;

    int scene = 1+int(mod(0.1*iTime, 3.));
    if (keyToggle( 49)) scene = 0;
    if (keyToggle( 50)) scene = 1;
    if (keyToggle( 51)) scene = 2;


    float amplification_amplitude, SDF_to_amplify, SDF_to_amplify_lip_const, SDF_to_amplify_oriented_lip_const;
    switch (scene){
        case 0:
            break;
        case 1:
            // SPHERE
            float amplification_amplitude = 0.6+0.5*cos(iTime*0.875);
            amplification_amplitude = 1.5;

            SDF_to_amplify = SDF_to_hypertexture(p);

            SDF_to_amplify_lip_const = 1.;
            SDF_to_amplify_oriented_lip_const = SDF_to_amplify_lip_const; // When you know how to compute it, put it here to make affine approx of SDF with respect to ray direction, else use worst case affine approx (i.e. linear bounding function)

            noise_threshold_b = SDF_to_amplify * 1./amplification_amplitude;
            noise_threshold_a = SDF_to_amplify_oriented_lip_const *-1. *1./amplification_amplitude;

            p.y += iTime*0.5; // to animate with time
            break;
        case 2:
            // ARLO
            amplification_amplitude = 0.6+0.5*cos(iTime*0.875);

            float SDF_scaling = 0.5;
            amplification_amplitude *= 1./SDF_scaling;
            SDF_to_amplify = mapArlo(p*1./SDF_scaling).x;;

            SDF_to_amplify_lip_const = 1.*1./SDF_scaling;
            SDF_to_amplify_oriented_lip_const = SDF_to_amplify_lip_const; // When you know how to compute it, put it here to make affine approx of SDF with respect to ray direction, else use worst case affine approx (i.e. linear bounding function)

            noise_threshold_b = SDF_to_amplify * 1./amplification_amplitude;
            noise_threshold_a = SDF_to_amplify_oriented_lip_const *-1. *1./amplification_amplitude;

            p.y += iTime*0.5; // to animate with time
            break;
    }

    noise_varying_threshold = vec2(noise_threshold_b ,noise_threshold_a);
}
#endif

// ========== PARAMETERS END ==========










// ========== FBM ==========
vec2 FBM_base_noise(vec3 p, vec3 rd, bool should_comp_grad){
    #ifdef OVERWIRTE_FBM_BASE_NOISE_FUNCTIONS
    return FBM_base_noise_OVERWRITE(p,rd,should_comp_grad);
    #else
    return FBM_base_noise_default(p,rd,should_comp_grad);
    #endif
}
vec4 FBM_base_noise_lip_consts(){
     vec4 base_scaling=vec4(FBM_BASE_SCALE, FBM_BASE_SCALE*FBM_BASE_SCALE, FBM_BASE_SCALE*FBM_BASE_SCALE*FBM_BASE_SCALE, FBM_BASE_SCALE*FBM_BASE_SCALE*FBM_BASE_SCALE*FBM_BASE_SCALE);
    #ifdef OVERWIRTE_FBM_BASE_NOISE_FUNCTIONS
    return base_scaling*FBM_base_noise_lip_consts_OVERWRITE();
    #else
    return base_scaling*FBM_base_noise_lip_consts_default();
    #endif
}


float FBM_skip_dist(vec3 p,int n, out float skipable_dist, vec2 affine_threshold, vec3 rd, float beta,
    bool do_early_stop, bool do_quad_skip, bool do_substepping, float do_full_comp_for_sign, int early_stop_plus_k, bool do_use_global_lip, bool use_improved_quad
    ){
    vec4 lip_consts = FBM_base_noise_lip_consts();

    float ampl = 1., F = 0.;
    skipable_dist = 0.;
    vec3 base_p = p;
    float F_der = 0.; // magnitude of F gradient in in ray direction

    float ampl_factor = pow(2., -beta); // If beta = 0., creates divide by zero in some places
    float d1_factor = 2.*ampl_factor; // equivalent to pow(2., 1.-beta);
    float d2_factor = 2.*d1_factor; // equivalent to pow(2., 2.-beta);

    float s_n_inf = pow(ampl_factor, float(n))/(1.-ampl_factor); // float moreThanMaxOctaveSumMax = 1./pow(2., float(octave)-1.); // Sigma(n=o, octave)(1./2^(n)) = 1./2^(o-1) - 1./2^(omax-1) = a - 1./2^(omax-1)
    float s_1_inf = 1./(1. - ampl_factor);
    float s_1_n = s_1_inf-s_n_inf;
    affine_threshold *= s_1_n;  // Because F is divided by s_1_n to renormalize it at the end, we can do this instead of changing lip constants and values when computing step size

    for (float i=0.; int(i)<(n); i+=1.){               COUNTER_PLUS1(COUNTER_nbr_octave_computed);
        float o = i+1.; // current octave id
        vec2 f_i = FBM_base_noise(p, rd, true);
        float f_i_der = f_i.y;
        F += ampl*f_i.x;
        F_der += pow(d1_factor, o-1.)*f_i_der;
        float s_ip1_n = (ampl*ampl_factor)/(1.-ampl_factor) - s_n_inf;

        float threshold = affine_threshold.x;
        float sign_mult = sign(affine_threshold.x - F); // Used to invert sign in multiple places for rays starting inside the shape (negative SDF)

        if ((abs(F-threshold) > s_ip1_n*1.0) // Test if outside of BVH_i
            && (do_full_comp_for_sign == 0. || do_full_comp_for_sign != -sign_mult)
            && (!do_use_global_lip || (do_use_global_lip && (do_early_stop || float(n)-1. == i)) )
        ){
            if (do_use_global_lip){ // For when adaptive lip is disabled
                o = float(n);
            }

            // Adaptive lip constants comp
            float d1_mult = beta == 1. ? o : (   (1.-pow(d1_factor, o))/(1.-d1_factor)    );  // For beta in ]0,2]
            float d2_mult = beta == 2. ? o : (   (1.-pow(d2_factor, o))/(1.-d2_factor)    );  // For beta in ]0,2]
                // Could remove need for pow() computation at each step by caching it like "ampl" variable, but uses more registers.
            float lambda_F = d1_mult * lip_consts.x;  // adaptive 1st order lip const
            float gamma_F = d2_mult * lip_consts.y; // adaptive 2nd oder lip const

            float BVH_i = sign_mult*F + s_ip1_n;
            float sign_corrected_F_der = sign_mult*F_der; 
            vec2 sign_corrected_thresh = vec2(sign_mult*affine_threshold.x,affine_threshold.y);

            float curr_skipable_dist; // Compute x coordinate of intersection point btw inclusion function of F and affine threshold
            if (do_quad_skip){
                curr_skipable_dist = compute_quad_taylor_skip(BVH_i, sign_corrected_F_der, gamma_F, lambda_F, sign_corrected_thresh, use_improved_quad);
            } else {
                curr_skipable_dist = compute_linear_skip(BVH_i, sign_corrected_thresh, lambda_F);
            }

            if (do_substepping && do_full_comp_for_sign != sign_mult){
                // Instead of keeping best skip_dist of versions with more or less octaves, we can move along the ray as the calculation goes to sum the skip_dists
                skipable_dist += sign_mult*curr_skipable_dist;
                // Since can move this much safely, can start moving along ray before computing next octaves
                p = (base_p+rd*abs(skipable_dist))*pow(2.,i); 
                affine_threshold.x += affine_threshold.y*abs(curr_skipable_dist); // Compute new threshold value at new position (threshold.y stays the same for affine)
                F = affine_threshold.x - sign_mult*s_ip1_n;      // Compute worst case value of F at new position, i.e. BVH_i = value of affine threshold at new position.
                F_der += sign_mult*gamma_F*(curr_skipable_dist);        // Compute wost case value of F_der at new position assuming quad taylor incl function
                F_der = sign_mult*min(sign_mult*F_der, lambda_F);   // Improved quadratic: the deriv is capped by the max deriv
            } else {
                skipable_dist = sign_mult*max(sign_mult*skipable_dist, curr_skipable_dist); // Keep best skip dist
            }

            if (do_early_stop){
                early_stop_plus_k --;
                if (early_stop_plus_k < 0)  break;
            }
        }
        p = p*2.; // Double frequency
        ampl = ampl*ampl_factor; // Mult amplitude
    }
    return F/s_1_n;
}



// ========== SAMPLING ==========
float compute_curr_min_step_size(float dist){    
    float curr_min_step_size = MIN_STEP_SIZE;
    #ifdef ADAPT_MIN_STEP_SIZE_TO_CAM_DIST
        curr_min_step_size = max(compute_sampling_wavelength(dist, FBM_OCTAVE, iResolution.xy, ADAPT_MIN_STEP_SIZE_TO_FBM_OCTAVE ), ADAPTIVE_MIN_STEP_SIZE);
        curr_min_step_size = min(ADAPTIVE_MAX_STEP_SIZE, curr_min_step_size);
    #else
    if(ADAPT_MIN_STEP_SIZE_TO_FBM_OCTAVE==true){
        curr_min_step_size = max(compute_sampling_wavelength(0., FBM_OCTAVE, iResolution.xy, ADAPT_MIN_STEP_SIZE_TO_FBM_OCTAVE ), ADAPTIVE_MIN_STEP_SIZE);
        curr_min_step_size = min(ADAPTIVE_MAX_STEP_SIZE, curr_min_step_size);
    }
    #endif
    return curr_min_step_size;
}

// ========== DISTANCE FUNCTION DEF ==========
float noise_SDB(vec3 p, vec3 rd, float curr_dist, out float skip_distance){
    skip_distance = 0.;
    float noise_threshold = FBM_TRESH;
    int octave = FBM_OCTAVE;
    #ifdef ADAPT_OCTAVE_TO_CAM_DIST
        float sampling_wavelength = compute_curr_min_step_size(curr_dist);

        int start_octave = 0;
        int end_octave = max(start_octave,min(2+int(-log2(sampling_wavelength)), octave));
        octave = end_octave;
    #endif

    float noise_freq = FBM_BASE_SCALE;
    vec2 noise_affine_threshold = vec2(0.);
    get_noise_params(p, rd, octave, noise_threshold, noise_affine_threshold);

    p*=noise_freq;
    float noise = 0.;

    float curr_min_step_size = MIN_STEP_SIZE;
    curr_min_step_size = compute_curr_min_step_size(curr_dist);

    bool do_early_stop = DO_EARLY_STOP, do_quad_skip = DO_QUAD_SKIP, do_substepping = DO_SUBSTEPPING, do_use_global_lip = DO_USE_GLOBAL_LIP, use_improved_quad = USE_IMPROVED_QUAD;
    float do_full_comp_for_sign = DO_FULL_COMP_FOR_SIGN, beta = BETA;
    int early_stop_plus_k = EARLY_STOP_PLUS_K, exit_oct = 0;

    if(KEYBOARD_CONTROLED_OPTIONS){
        bool apply_ours = true;
        if (apply_ours){
            do_use_global_lip = false;
            do_early_stop = true;
            do_quad_skip = true;
            do_substepping = true;
            use_improved_quad = true;
        }
        bool apply_custom = keyToggle(67);
        bool apply_naive = keyToggle(78);
        if (apply_naive && !apply_custom){
            do_use_global_lip = true;
            do_early_stop = false;
            do_quad_skip = false;
            do_substepping = false;
            use_improved_quad = false;
        }

        if (apply_custom){
            do_early_stop = do_early_stop ^^ keyToggle(69);
            do_quad_skip = do_quad_skip ^^ keyToggle(81);
            do_substepping = do_substepping ^^ keyToggle(83);
            do_use_global_lip = do_use_global_lip ^^ keyToggle(65);
            use_improved_quad = use_improved_quad ^^ keyToggle(73);
        }
    }

    noise = FBM_skip_dist(p, octave, skip_distance, noise_affine_threshold, normalize(rd), beta,
        do_early_stop, do_quad_skip, do_substepping, do_full_comp_for_sign, early_stop_plus_k, do_use_global_lip, use_improved_quad
    );

    bool do_ray_marching = DO_RAY_MARCHING;
    if (do_ray_marching){
        if (noise < noise_threshold){
            skip_distance = curr_min_step_size;
        } else {
            skip_distance = -curr_min_step_size;
        }
    }
    p/=noise_freq;

    return noise;
}

float SDB(vec3 p, vec3 rd, float dist){
    float skip_dist = 0.;
    float noise = noise_SDB(p, rd, dist, skip_dist);
    return skip_dist;
}

// ========== SPHERE TRACING ==========
float sphereTracing(vec3 ro, vec3 rd, float start_dist, float end_dist, inout int step_count) {
    float min_step_size = MIN_STEP_SIZE;
    int max_step_count = MAX_STEPS;

    float max_dist = min(end_dist, MAX_DIST);

	float dist=start_dist, in_dist = start_dist;
    vec3 p = ro + dist*rd;

    float step_size = 0.;
    float last_step_size = 0.;

    for (;step_count < max_step_count; step_count++ ){
        p = ro + dist*rd;

        step_size = SDB(p, rd, dist);
        if ( step_size < 0.){
            in_dist = dist-(-step_size); // step back toward true value (but might still be in negative side)
            in_dist = dist-last_step_size; // revert to positive side (but might be less precise)

            step_count++;
            break;
        }

        float curr_min_step_size = compute_curr_min_step_size(dist);
        last_step_size = max(curr_min_step_size, abs(step_size));

        dist += last_step_size;
        if (dist> max_dist){
            break;
        }
    }

    if (step_count == max_step_count || dist> max_dist){
        return max_dist;
    }
    return in_dist;
}

// ========== BBOX ==========
vec2 iRay(vec3 ro, vec3 rd){
    float bbox_scale = BBOX_SCALE;
    vec3 bbox_p1 = vec3(-2., -2., -2.)*bbox_scale;
    vec3 bbox_p2 = vec3(2., 2., 2.)*bbox_scale;
    return iAABBox(ro, rd, bbox_p1, bbox_p2);
}


// ========== MAIN ==========
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord.xy-(0.5*iResolution.xy))/iResolution.y;
    uv*=0.45; // zoom without getting closer, reduced fov
    vec2 m_uv = iMouse.xy == vec2(0.) ? vec2(0.5,0.4) : iMouse.xy/iResolution.xy;
    #ifdef iMOUSE_OVERWRITE
        m_uv = iMOUSE_OVERWRITE/vec2(1024.);
    #endif
    #ifdef SCALE_OVERWRITE
        scale = SCALE_OVERWRITE;
    #endif

    vec3 ro, rd;
    Cam(ro, rd, uv, m_uv, scale);


    vec3 background = vec3(0.);
    vec3 col =vec3(0.);

    vec2 bbox_distances = iRay(ro, rd);
    vec3 T_acc = vec3(1.);

    bbox_distances.y = min(bbox_distances.y, MAX_DIST*scale);
    bbox_distances.x = max(bbox_distances.x, 0.);

    #if ENABLE_BBOX ==0
        bbox_distances = vec2(0., MAX_DIST);
    #endif

    int step_count = 0;
    float dist = sphereTracing(ro, rd, bbox_distances.x, bbox_distances.y, step_count);

    #if DO_DISTANCE_VISU!=0
    if (dist < min(MAX_DIST, bbox_distances.y) && dist > bbox_distances.x){
        col = (vec3(1.) * (dist))*0.25*0.4;
    } else {
        col = background;
    }
    #endif

    #if DO_STEP_VISU!=0
        float step_count_f = float(step_count);
        float redBlueTresh = 150.;
        col = vec3(exp(-2.*step_count_f/redBlueTresh));
    #endif

    #if DO_OCT_PER_STEP_VISU!=0
        float avg_oct_per_step = float(COUNTER_nbr_octave_computed)/float(step_count);
        float norm_avg_oct_per_step = avg_oct_per_step/float(FBM_OCTAVE);
        col = vec3(norm_avg_oct_per_step, 1.-norm_avg_oct_per_step, 0.);
        col = vec3(norm_avg_oct_per_step);
        // col = vec3(floor(avg_oct_per_step) / float(FBM_OCTAVE), 0., 0.);
        // col = vec3(ceil(avg_oct_per_step) / float(FBM_OCTAVE));
    #endif

    #if DO_TOTAL_OCT_VISU!=0
    bool displayTotalOctaveColoring = DO_TOTAL_OCT_VISU==1;
    if (displayTotalOctaveColoring){
        col = vec3(float(COUNTER_nbr_octave_computed)*0.00005);
    }
    #endif

    if (DO_TOTAL_OCT_HEATMAP_VISU!=0 && ! keyToggle(72)){
        if (DO_TOTAL_OCT_HEATMAP_VISU != 2 || uv.x>0.){
            #ifndef TOTAL_OCT_SHADING_LOW_TRESH 
                #define TOTAL_OCT_SHADING_LOW_TRESH 50 
            #endif
            #ifndef TOTAL_OCT_SHADING_HIGH_TRESH 
                #define TOTAL_OCT_SHADING_HIGH_TRESH 10000
            #endif
            #ifndef TOTAL_OCT_SHADING_LOW_COL 
                #define TOTAL_OCT_SHADING_LOW_COL vec3(0.,0.,1.)
            #endif
            #ifndef TOTAL_OCT_SHADING_MED_COL 
                #define TOTAL_OCT_SHADING_MED_COL vec3(1.,1.,1.)
            #endif
            #ifndef TOTAL_OCT_SHADING_HIGH_COL 
                #define TOTAL_OCT_SHADING_HIGH_COL vec3(1.,0.,0.)
            #endif

            int blue_oct_thresh = TOTAL_OCT_SHADING_LOW_TRESH;
            int red_oct_thresh = TOTAL_OCT_SHADING_HIGH_TRESH;
            vec3 low_col = TOTAL_OCT_SHADING_LOW_COL;
            vec3 med_col = TOTAL_OCT_SHADING_MED_COL;
            vec3 high_col = TOTAL_OCT_SHADING_HIGH_COL;

            #ifndef SHADE_LOG
            col = ShadeSteps(COUNTER_nbr_octave_computed, blue_oct_thresh, red_oct_thresh, low_col, med_col, high_col);
            #else
            col = ShadeStepsLog(COUNTER_nbr_octave_computed, blue_oct_thresh, red_oct_thresh, low_col, med_col, high_col);
            #endif
            col = ShadeSteps(COUNTER_nbr_octave_computed, blue_oct_thresh, red_oct_thresh, low_col, med_col, high_col);
        }
    }


    col = pow(col,vec3(1./2.2));  //Gamma correction
    fragColor = vec4(col ,1.0);
}

#define keyDown(ascii)    ( texelFetch(iChannel3,ivec2(ascii,0),0).x > 0.)
#define keyToggle(ascii)  ( texelFetch(iChannel3,ivec2(ascii,2),0).x > 0.)

// --- chars
int CAPS=0;
#define low CAPS=32;
#define caps CAPS=0;
#define spc  U.x-=.5;
#define C(c) spc O+= char(U,64+CAPS+c);


//    === NATURAL LOD OPTIONS ===
#define ADAPT_MIN_STEP_SIZE_TO_CAM_DIST
    #define ADAPT_MIN_STEP_SIZE_TO_FBM_OCTAVE true
#define ADAPTIVE_MIN_STEP_SIZE 0.000001
#define ADAPTIVE_MAX_STEP_SIZE 10.
#define ADAPT_OCTAVE_TO_CAM_DIST

// ========== COUNTERS FOR VISU MODES ==========
int COUNTER_nbr_perlin = 0; 
int COUNTER_nbr_octave_computed = 0;
#define COUNTER_PLUS1(c) c++;

//    === SPHERE TRACING OPTIONS ===
#define MAX_STEPS 100000
#define MIN_STEP_SIZE 0.01
#define MAX_DIST 100.

// ========== HASH & PSEUDORANDOM DIR VECTOR ==========
uvec3 pcg3du(uvec3 v) {    // From  http://www.jcgt.org/published/0009/03/02/
    v = v * 1664525u + 1013904223u;
    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    // v = ((v >> int((v >> 28u) + 4u)) ^ v) * 277803737u;
    v ^= v >> 16u;
    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    return v;
}
#define to1uHashTo3uHash(h) uvec3(h*19,h*47, h*101)
#define uHashTofHash(h, v) (vec3(h( floatBitsToUint(v) ))) * (1.0/float(0xffffffffu));
//#define uHashTofHash(h, v) (uintBitsToFloat(h( floatBitsToUint(v) )));
vec3 pcg3d(vec3 v) {
    return uHashTofHash(pcg3du, v);
    // return vec3(pcg3du( floatBitsToUint(v) )) * (1.0/float(0xffffffffu));
}
//#define hash33(p) fract(sin((p)*mat3(127.1,311.7, 74.7,  269.5,183.3,246.1,  113.5,271.9,124.6))*43758.5453123)
#define hash33(p) pcg3d(p)
#define M_PI 3.14159265359
vec3 sample_uniform_dir_vector(float r1, float r2){   // From  https://www.scratchapixel.com/lessons/procedural-generation-virtual-worlds/perlin-noise-part-2/perlin-noise.html
    float cosTheta = (2. * r1 - 1.);
    float sinTheta = sqrt(1. - cosTheta*cosTheta);
    float phi = 2. * r2 * M_PI; 
    float x = cos(phi) * sinTheta;
    float y = sin(phi) * sinTheta;
    float z = cosTheta;
    return vec3(x, y, z);
}
