// ========== PERLIN ==========
const float perlin_normalization_factor = 1./sqrt(3./4.); // Normalizing. Max value for perlin is sqrt(N/4) with N the dimension https://digitalfreepen.com/2017/06/20/range-perlin-noise.html
const float max_base_perlin_derivative = 2.182518*perlin_normalization_factor; // https://github.com/rudi-c/perlin-range
const float max_base_perlin_scd_derivative = max_base_perlin_derivative*4.;


// Here we compute perlin & its numerical derivative in the ray direction (through finit difference), re-using the grid gradient vectors to make it faster
// This is faster than computing the full analytical gradient of perlin then dotting it with the ray direction, and is close enough that we didn't notice any quality change between the two 
vec2 perlin3D_with_der(in vec3 x, in vec3 rd, bool comp_gradient){
    COUNTER_PLUS1(COUNTER_nbr_perlin) // Used just for visualization
    vec3 i = floor(x);
    vec3 f = fract(x);
    const float offset = 0.001;
    // vec3 p2 = x + rd*offset; 
    // vec3 f2 = fract(p2);  // fract acts as modulo 1, so the small offset can result in big differences, this is bad
    vec3 f2 = f + rd*offset; // approximate at edges (good enough) but prevents artifacts of fract

    vec3 u = f*f*(3.0-2.0*f);
    vec3 u2 = f2*f2*(3.0-2.0*f2);
    // vec3 u2 = u*(1.+ o*( 2./f + o/(f*f) ));

    // gradients
    vec3 ga = rand_unit_vector( i+vec3(0,0,0) );
    vec3 gb = rand_unit_vector( i+vec3(1,0,0) );
    vec3 gc = rand_unit_vector( i+vec3(0,1,0) );
    vec3 gd = rand_unit_vector( i+vec3(1,1,0) );
    vec3 ge = rand_unit_vector( i+vec3(0,0,1) );
	vec3 gf = rand_unit_vector( i+vec3(1,0,1) );
    vec3 gg = rand_unit_vector( i+vec3(0,1,1) );
    vec3 gh = rand_unit_vector( i+vec3(1,1,1) );

    // projections
    float va = dot( ga, f-vec3(0.0,0.0,0.0) );
    float vb = dot( gb, f-vec3(1.0,0.0,0.0) );
    float vc = dot( gc, f-vec3(0.0,1.0,0.0) );
    float vd = dot( gd, f-vec3(1.0,1.0,0.0) );
    float ve = dot( ge, f-vec3(0.0,0.0,1.0) );
    float vf = dot( gf, f-vec3(1.0,0.0,1.0) );
    float vg = dot( gg, f-vec3(0.0,1.0,1.0) );
    float vh = dot( gh, f-vec3(1.0,1.0,1.0) );

    // interpolations
    float noise_v = va + u.x*(vb-va) + u.y*(vc-va) + u.z*(ve-va) + u.x*u.y*(va-vb-vc+vd) + u.y*u.z*(va-vc-ve+vg) + u.z*u.x*(va-vb-ve+vf) + (-va+vb+vc-vd+ve-vf-vg+vh)*u.x*u.y*u.z ;

    float noise_deriv = 0.; // Will compute derivative approx (in ray dir) through finite diff of two samples along the ray
    if (comp_gradient){ // Can compute perlin noise in the same grid cell using the same gradients and just different projections. 
                        // Sample point could be slighly outside of the grid cell, but this doesn't cause issue if close enough to the cell borders.

        // float va2 = dot( ga, f2-vec3(0.0,0.0,0.0) );
        // float vb2 = dot( gb, f2-vec3(1.0,0.0,0.0) );
        // float vc2 = dot( gc, f2-vec3(0.0,1.0,0.0) );
        // float vd2 = dot( gd, f2-vec3(1.0,1.0,0.0) );
        // float ve2 = dot( ge, f2-vec3(0.0,0.0,1.0) );
        // float vf2 = dot( gf, f2-vec3(1.0,0.0,1.0) );
        // float vg2 = dot( gg, f2-vec3(0.0,1.0,1.0) );
        // float vh2 = dot( gh, f2-vec3(1.0,1.0,1.0) );

        // Equivalent math, not sure if faster or not
        float va2 = va + dot( ga, rd*offset );
        float vb2 = vb + dot( gb, rd*offset );
        float vc2 = vc + dot( gc, rd*offset );
        float vd2 = vd + dot( gd, rd*offset );
        float ve2 = ve + dot( ge, rd*offset );
        float vf2 = vf + dot( gf, rd*offset );
        float vg2 = vg + dot( gg, rd*offset );
        float vh2 = vh + dot( gh, rd*offset );

        // interpolations
        float noise_v2 = va2 + u2.x*(vb2-va2) + u2.y*(vc2-va2) + u2.z*(ve2-va2) + u2.x*u2.y*(va2-vb2-vc2+vd2) + u2.y*u2.z*(va2-vc2-ve2+vg2) + u2.z*u2.x*(va2-vb2-ve2+vf2) + (-va2+vb2+vc2-vd2+ve2-vf2-vg2+vh2)*u2.x*u2.y*u2.z ;
        noise_deriv = (noise_v2-noise_v)/offset; // finit diff
    }

    vec2 noise = vec2(noise_v, noise_deriv);
    noise *= perlin_normalization_factor;
    return noise;
}



