// ========== 1D basic root solving ==========
float taylorExpPoly2nd(float x, float a, float f_a, float f_a_der, float f_a_2ndDer){
    return f_a + f_a_der*(x-a) + f_a_2ndDer*(x-a)*(x-a)*0.5;
}

#define SKIP_STEP_SIZE_INFINIT 9999.
float compute_quad_taylor_skip(float f_a, float f_a_der, float f_a_2ndDer, float f_max_der, vec2 thresh, bool use_improved_quad){
    float thresh_a = thresh.y;
    float thresh_b = thresh.x;

    float a_root = f_a_2ndDer * 0.5;
    float b_root = f_a_der - thresh_a;
    float c_root = f_a - thresh_b;

    if (use_improved_quad == false){ // Regular quadratic root solving
        float d_skip_taylor = (-b_root + sqrt(max(0., b_root*b_root - 4. * a_root*c_root)))/(2. * a_root);
        return d_skip_taylor;
    }

    // Improved quadratic
    // Switch to linear if derivative of quadratic goes over input max derivative 

    // Compute where deriv of quad will go over max deriv
    float d_taylorDerivOverNoiseDeriv = (f_max_der - f_a_der) / (2. * a_root);
    d_taylorDerivOverNoiseDeriv = a_root != 0. ? d_taylorDerivOverNoiseDeriv: 0.;
    // Compute value of quad at this location
    float f_taylor_taylorDerivOverNoiseDeriv = taylorExpPoly2nd(d_taylorDerivOverNoiseDeriv, 0., f_a, f_a_der, f_a_2ndDer);
    // Compute (affine) threshold value at this location
    float thresh_at_taylorDerivOverNoiseDeriv = thresh_b + thresh_a*d_taylorDerivOverNoiseDeriv;

    float skipable_dist = 0.;
    // If when derive go over max deriv we are still under thresh, than we switch to linear from this point, else we compute root of quad
    if (f_taylor_taylorDerivOverNoiseDeriv < thresh_at_taylorDerivOverNoiseDeriv || a_root==0.){ // Linear
        float d_fromTaylorToLine = (thresh_at_taylorDerivOverNoiseDeriv - f_taylor_taylorDerivOverNoiseDeriv ) / (f_max_der-thresh_a) + d_taylorDerivOverNoiseDeriv;
        skipable_dist = d_fromTaylorToLine;

        if (d_fromTaylorToLine < 0. ){ // means that curr_skipable_dist will be negative or infinite 
            skipable_dist = SKIP_STEP_SIZE_INFINIT;
        }
    } else { // Quadratic
        float d_skip_taylor = (-b_root + sqrt(max(0., b_root*b_root - 4. * a_root*c_root)))/(2. * a_root); // max might not be needed
        skipable_dist = d_skip_taylor;
    }

    return skipable_dist;
}


float compute_linear_skip(float r, vec2 min_noise_threshold, float max_fbm_derivative){
    float norm_min_noise_threshold_b = min_noise_threshold.x;
    float norm_min_noise_threshold_a = min_noise_threshold.y;
    float skipable_dist = -(r -norm_min_noise_threshold_b)/(max_fbm_derivative-norm_min_noise_threshold_a);
    return skipable_dist;
}

// ========== SAMPLING ==========
float compute_sampling_wavelength(float dist, int FBM_OCTAVE, vec2 iResolution, bool adapt_MIN_STEP_SIZE_TO_FBM_OCTAVE){
    float world_scale = 1.;

    float base_pixel_world_footprint = world_scale*1./iResolution.y; // Should take fov and aspect ratio into account here to be correct
    float distant_pixel_world_footprint = base_pixel_world_footprint * dist;

    float sampling_wavelength = 2.*distant_pixel_world_footprint;

    //#ifdef ADAPT_MIN_STEP_SIZE_TO_FBM_OCTAVE
    if (adapt_MIN_STEP_SIZE_TO_FBM_OCTAVE){
        sampling_wavelength = max(sampling_wavelength, 0.01*1./pow(2.,float(FBM_OCTAVE)));
    //#endif
    }
    return sampling_wavelength;
}


// ========== BBOX ==========
vec2 iBBox( in vec3 ro, in vec3 rd, in vec3 cen, in vec3 rad ){ // ray-box intersection in box space //Taken from IQ's shader : https://www.shadertoy.com/view/tsBfRD
    vec3 m = 1.0/rd;
    vec3 n = m*(ro-cen);
    vec3 k = abs(m)*rad;

    vec3 t1 = -n - k;
    vec3 t2 = -n + k;

	float tN = max( max( t1.x, t1.y ), t1.z );
	float tF = min( min( t2.x, t2.y ), t2.z );

	if( tN > tF || tF < 0.0) return vec2(-1.0);
	return vec2( tN, tF );
}

vec2 iAABBox( in vec3 ro, in vec3 rd, in vec3 bbox_p_min, in vec3 bbox_p_max ){
    vec3 bbox_cen = 0.5*(bbox_p_min+bbox_p_max);
    vec3 bbox_rad = 0.5*(bbox_p_max-bbox_p_min);
    return iBBox(ro, rd, bbox_cen, bbox_rad);
}


