vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 cam_dir = -normalize(l-p),
        right = normalize(cross(vec3(0,1,0), cam_dir)),
        up = cross(cam_dir,right),
        c = -cam_dir*z,
        i = c + uv.x*right + uv.y*up,
        d = normalize(i);
    return d;
}

