vec3 ShadeSteps(int n, int start, int end, vec3 col_low, vec3 col_med, vec3 col_high)
{
    int range_span = (end - start);
    float val = max(0., float(n) - float(start));
    float t = val/float(range_span);

    // return hue(t*0.5+0.4).xyz;
    if (t < 0.5)
        return mix(col_low, col_med, 2.0 * t);
    else
        return mix(col_med, col_high, 2.0 * t - 1.0);
}


